import { INITIAL_DATA, APP_META, TEACHER_ALIASES } from './data.js';
import * as db from './database.js';
import * as cloud from './supabase-sync.js';

const $ = (s,r=document)=>r.querySelector(s);
const $$ = (s,r=document)=>[...r.querySelectorAll(s)];
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const todayISO=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
const deviceNow=()=>new Date();
const deviceClock=()=>{const d=deviceNow();return {date:todayISO(),time:d.toTimeString().slice(0,5),timestamp:d.getTime()};};
const deviceTime=()=>deviceNow().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
const timeToMinutes=v=>{if(!v)return 9999;const m=String(v).match(/^(\d{1,2}):(\d{2})/);return m?Number(m[1])*60+Number(m[2]):9999};
const rondaTiming=x=>{const clock=deviceClock();const date=String(x.date||'');if(date<clock.date)return {key:'overdue',label:'ATRASADA',className:'overdue'};if(date>clock.date)return {key:'future',label:'PRÓXIMA',className:'upcoming'};const now=timeToMinutes(clock.time),start=timeToMinutes(x.start);if(start===9999)return {key:'unknown',label:'SEM HORÁRIO',className:'unknown'};if(now<start)return {key:'future',label:'PRÓXIMA',className:'upcoming'};if(now<start+10)return {key:'live',label:'NO HORÁRIO',className:'active'};return {key:'overdue',label:'ATRASADA',className:'overdue'};};
const fmtDate=v=>v?new Date(v+'T00:00:00').toLocaleDateString('pt-BR'): '—';
const statusClass=s=>{s=(s||'').toLowerCase();if(s.includes('presente'))return'present';if(s.includes('substit'))return'substitute';if(s.includes('atras'))return'late';if(s.includes('falta')||s.includes('ausente')||s.includes('localizado'))return'absent';if(s.includes('just'))return'justified';if(s.includes('unific')||s.includes('cancel')||s.includes('outro'))return'other';return'pending'};
const unique=a=>[...new Set(a.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'pt-BR'));
const state={view:'dashboard',schedule:[],inspections:[],rounds:[],settings:{},date:todayISO(),search:'',status:'',historyMonth:todayISO().slice(0,7),historyStatus:'',historySearch:'',selectedTeacher:'',skippedRounds:loadSkippedRounds()};
const titles={dashboard:'Início',ronda:'Rondas',escala:'Escala',historico:'Histórico',professores:'Professores',ficha:'Ficha do docente',salas:'Salas',relatorios:'Relatórios',config:'Configurações'};

window.addEventListener('error',e=>console.error('Fiscaliza Docente:',e.error||e.message));

document.addEventListener('DOMContentLoaded',async()=>{
  try{
    bindNavigation();
    const rebuildMarker=await db.get('settings','workbookRebuildV6131');
    if(rebuildMarker?.done!==true){
      // Importação completa V6.13.1: substitui escala e histórico locais uma única vez pela planilha atualizada.
      await db.clearStore('schedule'); await db.clearStore('inspections');
      await db.bulkPut('schedule', INITIAL_DATA.schedule.map(x=>({...x, roomChecks: normalizeRoomChecks(x)})));
      for (const item of INITIAL_DATA.inspections) { const copy = {...item, source: item.source || 'Planilha de Controle Docente', imported: true}; delete copy.id; await db.add('inspections', copy); }
      await db.put('settings',{key:'workbookRebuildV6131',done:true,at:new Date().toISOString(),scheduleCount:INITIAL_DATA.schedule.length,inspectionCount:INITIAL_DATA.inspections.length});
    }
    await db.seedIfEmpty(INITIAL_DATA);
    await syncScheduleMetadata();
    await syncInspectionTeacherNames();
    await reload();
    await migrateLegacyRoomChecks();
    await splitThreeRoomLessonRecords();
    await reload();
    await ensureUnregisteredRooms(state.date);
    await reload();
    render();
    setTimeout(async()=>{
      try {
        const marker=await db.get('settings','duplicateCleanupVersion');
        if(marker?.version===10) return;
        await cleanupDuplicateData();
        await reload();
        render();
        toast('Base revisada: duplicidades removidas com segurança.');
      } catch(err) {
        console.error('Limpeza automática:',err);
        toast('A limpeza automática não foi concluída. Seus dados foram preservados.','error');
      }
    },250);
  }catch(err){console.error(err);showError(err.message||'Falha ao iniciar o aplicativo.');}
});

function bindNavigation(){
  document.addEventListener('click',e=>{
    const v=e.target.closest('[data-view]');
    if(v){e.preventDefault();navigate(v.dataset.view);return;}
    const concludeReturn=e.target.closest('[data-conclude-followup]');
    if(concludeReturn){e.preventDefault();concludeFollowUp(concludeReturn.dataset.concludeFollowup, concludeReturn.dataset.room);return;}
    const inspect=e.target.closest('[data-inspect]');
    if(inspect){e.preventDefault();openInspection(inspect.dataset.inspect, inspect.dataset.inspectMode||'normal', inspect.dataset.inspectRoom||'');return;}
    const next=e.target.closest('[data-next-ronda]');
    if(next){e.preventDefault();const item=nextRonda();if(item){state.date=item.date;state.view='ronda';render();window.scrollTo({top:0,behavior:'smooth'});}return;}
    const skip=e.target.closest('[data-skip-ronda]');
    if(skip){e.preventDefault();const item=skipCurrentRound();if(item){state.date=item.date;state.view='ronda';render();toast('Ronda pulada sem registrar ocorrência. Próxima ronda carregada.');}else{render();toast('Não há outra ronda pendente.');}return;}
    const clearSkip=e.target.closest('[data-clear-skips]');
    if(clearSkip){e.preventDefault();clearSkippedForDate(state.date);render();toast('Rondas puladas foram reabertas.');return;}
    const restoreSkip=e.target.closest('[data-restore-skip]');
    if(restoreSkip){e.preventDefault();restoreSkippedRound(restoreSkip.dataset.restoreSkip);render();toast('Ronda devolvida à fila.');return;}
    const newClass=e.target.closest('[data-new-class]');
    if(newClass){e.preventDefault();openNewClass();return;}
    const teacher=e.target.closest('[data-teacher]');
    if(teacher){e.preventDefault();state.selectedTeacher=teacher.dataset.teacher;state.view='ficha';render();window.scrollTo({top:0,behavior:'smooth'});return;}
    const back=e.target.closest('[data-back-professores]');
    if(back){e.preventDefault();state.selectedTeacher='';state.view='professores';render();return;}
    const go=e.target.closest('[data-go]');
    if(go){e.preventDefault();navigate(go.dataset.go);return;}
  });
  document.addEventListener('change',e=>{if(e.target.matches('[data-dashboard-date]')){const value=e.target.value;if(value){state.date=value;render();}}});
  $('#menuBtn').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#backdrop').classList.add('show')});
  $('#backdrop').addEventListener('click',closeMenu);
  $('#moreBtn').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#backdrop').classList.add('show')});
  $('#closeDialog').addEventListener('click',closeDialog);$('#cancelDialog').addEventListener('click',closeDialog);const concludeDialog=$('#concludeFollowupDialog');if(concludeDialog)concludeDialog.addEventListener('click',async()=>{const sid=concludeDialog.dataset.scheduleId,room=concludeDialog.dataset.room;closeDialog();await concludeFollowUp(sid,room);});
  $('#inspectionForm').addEventListener('submit',saveInspection);$('#addPresentTeacher').addEventListener('click',()=>{const wrap=$('#extraTeachers');const row=document.createElement('div');row.className='extra-teacher-row';row.style.cssText='display:flex;gap:6px;align-items:end;margin-top:6px';const label=document.createElement('label');label.style.flex='1';label.textContent='Outro professor presente';const input=document.createElement('input');input.className='control fTeacherEntry';input.setAttribute('list','teacherList');input.setAttribute('autocomplete','off');input.placeholder='Nome do professor';label.appendChild(input);const remove=document.createElement('button');remove.type='button';remove.className='btn ghost small danger';remove.textContent='Remover';remove.addEventListener('click',()=>row.remove());row.append(label,remove);wrap.appendChild(row);input.focus();});$('#newClassForm').addEventListener('submit',saveNewClass);$('#closeClassDialog').addEventListener('click',closeNewClass);$('#cancelClassDialog').addEventListener('click',closeNewClass);
}
function closeMenu(){$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('show')}
function navigate(view){if(!titles[view])view='dashboard';state.view=view;closeMenu();$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('.bottom-nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();window.scrollTo({top:0,behavior:'smooth'})}
async function reload(){state.schedule=await db.getAll('schedule');state.inspections=await db.getAll('inspections');state.settings=await db.get('settings','app')||{};state.rounds=loadRounds();populateTeachers()}
const REQUIRED_ROOMS=['103','109','201','301','305','401','302','402','405','408','507','510','503','502','Auditório'];
const roomShift=x=>{const start=timeToMinutes(x.start);const period=normRoomForMatch(x.period||'');if(period.includes('manha')||period.includes('matut'))return 'manha';if(period.includes('tarde')||period.includes('vespert'))return 'tarde';if(start!==9999)return start<12*60?'manha':'tarde';return '';};
async function ensureUnregisteredRooms(date){
 if(!date)return;const existing=await db.getAll('schedule');const dayRows=existing.filter(x=>String(x.date||'')===String(date));const writes=[];
 // Hoje à tarde, criar somente conferências da tarde. Em datas futuras, manter os dois turnos.
 const shifts=(date===todayISO()&&timeToMinutes(deviceTime())>=12*60)?['tarde']:['manha','tarde'];
 for(const room of REQUIRED_ROOMS){const key=normRoomForMatch(room);for(const shift of shifts){
   const actualExists=dayRows.some(x=>!x.unregisteredRoom&&splitRooms(x.room).some(r=>normRoomForMatch(r)===key)&&roomShift(x)===shift);
   const placeholderExists=dayRows.some(x=>x.unregisteredRoom&&normRoomForMatch(x.room)===key&&roomShift(x)===shift);
   if(actualExists||placeholderExists)continue;
   writes.push({id:crypto.randomUUID(),date,day:new Date(date+'T00:00:00').toLocaleDateString('pt-BR',{weekday:'long'}),start:shift==='manha'?'08:00':'13:00',end:shift==='manha'?'11:59':'17:00',period:shift==='manha'?'Manhã — Verificação de sala':'Tarde — Verificação de sala',room,scheduledTeacher:'',subject:'Sem aula registrada — verificar se há aula',status:null,recordStatus:'Pendente',unregisteredRoom:true,roomShift:shift,roomChecks:[emptyRoomCheck(room)],createdAt:new Date().toISOString(),source:'Salas para conferência'});
 }}if(writes.length)await db.bulkPut('schedule',writes)
}
async function splitThreeRoomLessonRecords(){
 const marker=await db.get('settings','split103402405V1');if(marker?.done)return;
 const all=await db.getAll('schedule');const inspections=await db.getAll('inspections');
 for(const x of all){if(x.unregisteredRoom)continue;const rooms=splitRooms(x.room);const roomNums=rooms.map(r=>(String(r).match(/(103|402|405)\s*$/)||[])[1]).filter(Boolean);if(roomNums.length!==3||new Set(roomNums).size!==3||!['103','402','405'].every(n=>roomNums.includes(n)))continue;
   const checks=roomProgress(x).checks;const created=[];
   for(const num of ['103','402','405']){const check=checks.find(c=>(String(c.room).match(/(103|402|405)\s*$/)||[])[1]===num);const room=check?.room||rooms.find(r=>String(r).endsWith(num));if(!room)continue;const suffix=num;created.push({...x,id:`${x.id}-SALA-${suffix}`,room,roomChecks:[{...(check||emptyRoomCheck(room)),room}],status:check?.done?(check.status||null):null,recordStatus:check?.done?'Fiscalizado':'Pendente',presentTeacher:check?.presentTeacher||'',presentRoom:check?.presentRoom||room,checkedTime:check?.checkedTime||'',realStart:check?.realStart||'',realEnd:check?.realEnd||'',notes:check?.notes||'',followUpPending:!!check?.followUpPending,splitFromMultiRoom:true,splitRoomNumber:num});}
   if(created.length!==3)continue;
   await db.bulkPut('schedule',created);
   for(const i of inspections.filter(i=>String(i.scheduleId)===String(x.id))){const n=(String(i.plannedRoom||i.presentRoom||'').match(/(103|402|405)\s*$/)||[])[1];if(!n)continue;const dest=created.find(r=>r.splitRoomNumber===n);if(!dest)continue;const copy={...i,id:crypto.randomUUID(),scheduleId:dest.id};await db.put('inspections',copy);await db.remove('inspections',i.id);}
   await db.remove('schedule',x.id);
 }
 await db.put('settings',{key:'split103402405V1',done:true,at:new Date().toISOString()});
}
async function migrateLegacyRoomChecks(){const inspections=await db.getAll('inspections');const schedules=await db.getAll('schedule');for(const x of schedules){let checks=normalizeRoomChecks(x);const rel=inspections.filter(i=>String(i.scheduleId||'')===String(x.id));for(const c of checks){const hit=rel.find(i=>splitRooms(i.plannedRoom||i.presentRoom||'').some(r=>normRoomForMatch(r)===normRoomForMatch(c.room)));if(hit){c.done=true;c.status=hit.status||c.status;c.presentTeacher=hit.presentTeacher||c.presentTeacher;c.presentRoom=hit.presentRoom||c.presentRoom||c.room;c.checkedTime=hit.checkedTime||c.checkedTime;c.realStart=(hit.realTime||'').split('/')[0]||c.realStart;c.realEnd=(hit.realTime||'').split('/')[1]||c.realEnd;c.notes=hit.notes||c.notes;c.followUpPending=!!hit.followUpPending;c.initialStatus=hit.initialStatus||c.initialStatus;c.initialCheckedTime=hit.initialCheckedTime||c.initialCheckedTime;c.initialNotes=hit.initialNotes||c.initialNotes;c.followUpCheckedTime=hit.followUpCheckedTime||c.followUpCheckedTime;c.followUpTeacher=hit.followUpTeacher||c.followUpTeacher;c.followUpNotes=hit.followUpNotes||c.followUpNotes;}}const complete=checks.every(c=>c.done);const next={...x,roomChecks:checks,recordStatus:complete?'Fiscalizado':'Pendente',status:complete?(checks.map(c=>c.status).filter(Boolean).length?(new Set(checks.map(c=>c.status).filter(Boolean)).size===1?checks.find(c=>c.status)?.status:'Fiscalização concluída'):null):null,followUpPending:checks.some(c=>c.followUpPending)};await db.put('schedule',next)}}
function normRoomForMatch(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[–—−]/g,'-').replace(/\s+/g,' ').trim().toLowerCase();}
async function cleanupDuplicateData(){
  const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/[–—−]/g,'-').replace(/\s+/g,' ');
  const roomKey=v=>splitRooms(v).map(norm).sort().join(' + ');
  const subjectKey=v=>String(v??'').split(/\n+/).map(norm).filter(Boolean).sort().join(' / ');
  const deletedRec=await db.get('settings','deletedScheduleIds')||{key:'deletedScheduleIds',ids:[]};
  const deleted=new Set((deletedRec.ids||[]).map(String)); const schedules=await db.getAll('schedule'); const inspections=await db.getAll('inspections');
  const key=x=>[norm(x.date),norm(x.start),norm(x.end),roomKey(x.room)].join('|');
  const groups=new Map(); for(const x of schedules){if(deleted.has(String(x.id)))continue;const k=key(x);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(x);}
  const removed=[];
  for(const group of groups.values()){
    if(group.length<2)continue;
    const score=x=>{const c=Array.isArray(x.roomChecks)?x.roomChecks:[];return c.filter(v=>v.done).length*10+(x.status?4:0)+(x.recordStatus==='Fiscalizado'?3:0)+(x.followUpPending?2:0)+(x.notes?1:0)};
    group.sort((a,b)=>score(b)-score(a)||String(a.id).localeCompare(String(b.id))); const keep=group[0]; let merged=normalizeRoomChecks(keep); const mergedTeachers=unique(group.flatMap(g=>String(g.scheduledTeacher||'').split(/\s*\/\s*|\s*;\s*|\s*\|\s*|\s*\n\s*/).map(canonicalTeacher).filter(Boolean)));
    for(const drop of group.slice(1)){
      const dc=normalizeRoomChecks(drop); for(const d of dc){const idx=merged.findIndex(c=>norm(c.room)===norm(d.room));if(idx>=0&&d.done&&!merged[idx].done)merged[idx]={...merged[idx],...d,room:merged[idx].room};}
      const rel=inspections.filter(i=>String(i.scheduleId)===String(drop.id));
      for(const i of rel){const rk=roomKey(i.presentRoom||i.plannedRoom);const duplicate=inspections.find(j=>String(j.scheduleId)===String(keep.id)&&roomKey(j.presentRoom||j.plannedRoom)===rk&&norm(j.status)===norm(i.status)&&norm(j.checkedTime)===norm(i.checkedTime)&&norm(j.notes)===norm(i.notes));if(!duplicate)await db.put('inspections',{...i,scheduleId:keep.id});if(i.id!=null)await db.remove('inspections',i.id);}
      await db.remove('schedule',drop.id); removed.push(drop.id);
    }
    const mergedSubjects=unique(group.flatMap(g=>String(g.subject||'').split(/\n+/).map(v=>v.trim()).filter(Boolean))); const mergedPeriods=unique(group.flatMap(g=>String(g.period||'').split(/\s*\/\s*/).map(v=>v.trim()).filter(Boolean))); const complete=merged.length>0&&merged.every(c=>c.done); await db.put('schedule',{...keep,scheduledTeacher:mergedTeachers.join(' / '),subject:mergedSubjects.join('\n'),period:mergedPeriods.join(' / '),roomChecks:merged,recordStatus:complete?'Fiscalizado':'Pendente',status:complete?roomStatusSummary({...keep,roomChecks:merged}):null,followUpPending:merged.some(c=>c.followUpPending)});
  }
  const current=await db.getAll('inspections'); const seen=new Map();
  for(const i of current){const k=[norm(i.date),norm(i.scheduledTeacher||i.assignedName),norm(i.presentTeacher),roomKey(i.presentRoom||i.plannedRoom),norm(i.status),norm(i.checkedTime),norm(i.realTime),norm(i.notes),norm(i.followUpCheckedTime),norm(i.followUpTeacher),norm(i.followUpNotes)].join('|');if(!seen.has(k)){seen.set(k,i);continue;}const old=seen.get(k);const keep=String(i.updatedAt||i.createdAt||'')>String(old.updatedAt||old.createdAt||'')?i:old;const drop=keep===i?old:i;seen.set(k,keep);if(drop.id!=null)await db.remove('inspections',drop.id);}
  if(removed.length)await db.put('settings',{key:'deletedScheduleIds',ids:[...new Set([...deleted,...removed])]}); await db.put('settings',{key:'duplicateCleanupVersion',version:10,ranAt:new Date().toISOString(),removedSchedules:removed.length});
}
async function deleteRound(id){
  const x=state.schedule.find(r=>String(r.id)===String(id)); if(!x){toast('Ronda não encontrada.','error');return;}
  const label=`${fmtDate(x.date)} • ${x.start||'--:--'} • ${x.room||'sala não definida'} • ${x.scheduledTeacher||'professor não informado'}`;
  if(!confirm(`Excluir definitivamente esta ronda?\n\n${label}\n\nA ronda e seus registros de fiscalização serão removidos e ela não voltará pela sincronização.`))return;
  const rec=await db.get('settings','deletedScheduleIds')||{key:'deletedScheduleIds',ids:[]}; const ids=new Set((rec.ids||[]).map(String));ids.add(String(x.id)); const related=await db.getAll('inspections');
  for(const i of related.filter(i=>String(i.scheduleId)===String(x.id)))if(i.id!=null)await db.remove('inspections',i.id); await db.remove('schedule',x.id); await db.put('settings',{key:'deletedScheduleIds',ids:[...ids]}); state.skippedRounds=state.skippedRounds.filter(k=>k!==roundKey(x));saveSkippedRounds();await reload();render();toast('Ronda excluída.');
}

function canonicalTeacher(name){if(!name)return name;return TEACHER_ALIASES[name]||name;}
async function syncInspectionTeacherNames(){const inspections=await db.getAll('inspections');const writes=[];for(const old of inspections){const next={...old};const a=canonicalTeacher(old.scheduledTeacher);const b=canonicalTeacher(old.presentTeacher);const c=canonicalTeacher(old.assignedName);if(a!==old.scheduledTeacher||b!==old.presentTeacher||c!==old.assignedName){if(old.scheduledTeacher!=null)next.scheduledTeacher=a;if(old.presentTeacher!=null)next.presentTeacher=b;if(old.assignedName!=null)next.assignedName=c;writes.push(next);}}if(writes.length)await db.bulkPut('inspections',writes)}
function splitRooms(room){const raw=String(room||'').split(/\s+e\s+/i).map(v=>v.trim()).filter(Boolean);if(raw.length<=1)return raw.length?raw:['Sala não definida'];const first=raw[0];const m=first.match(/^(.*?)(\d+[A-Za-z]?)$/);const prefix=m?m[1]:'';return raw.map((part,i)=>i===0?part:(/^\d/.test(part)&&prefix?prefix+part:part));}
function emptyRoomCheck(room){return {room,done:false,status:'',presentTeacher:'',presentRoom:'',checkedTime:'',realStart:'',realEnd:'',notes:'',followUpPending:false,followUpCheckedTime:'',followUpTeacher:'',followUpNotes:''};}
function normalizeRoomChecks(x){const rooms=splitRooms(x.room);const old=Array.isArray(x.roomChecks)?x.roomChecks.map(c=>({...c})):null;let checks=rooms.map(room=>{const found=old?.find(c=>String(c.room||'').trim()===room);return found?{...emptyRoomCheck(room),...found,room}:{...emptyRoomCheck(room)}});if(!old&&x.status&&rooms.length===1){checks=checks.map(c=>({...c,done:true,status:x.status,presentTeacher:x.presentTeacher||'',presentRoom:x.presentRoom||'',checkedTime:x.checkedTime||'',realStart:x.realStart||'',realEnd:x.realEnd||'',notes:x.notes||'',followUpPending:x.status==='Atraso'}));}return checks;}
async function syncScheduleMetadata(){const current=await db.getAll('schedule');const byId=new Map(current.map(x=>[String(x.id),x]));const writes=[];for(const base of INITIAL_DATA.schedule){const old=byId.get(String(base.id));if(!old){writes.push({...base,roomChecks:normalizeRoomChecks(base)});continue;}const merged={...old,...base};for(const key of ['status','presentTeacher','presentRoom','checkedTime','realStart','realEnd','notes','recordStatus','createdAt','updatedAt','verifiedBy','realTime','roomChecks','followUpPending','followUpCheckedTime','followUpTeacher','followUpNotes']){if(Object.prototype.hasOwnProperty.call(old,key))merged[key]=old[key];}merged.roomChecks=normalizeRoomChecks(merged);if(old.recordStatus==null&&old.status)merged.recordStatus='Fiscalizado';writes.push(merged);}if(writes.length)await db.bulkPut('schedule',writes)}
function loadRounds(){try{return JSON.parse(localStorage.getItem('fiscaliza-docente-rounds')||'[]')}catch{return []}}
function saveRounds(){localStorage.setItem('fiscaliza-docente-rounds',JSON.stringify(state.rounds))}
function loadSkippedRounds(){try{return JSON.parse(localStorage.getItem('fiscaliza-docente-skipped-rounds')||'[]')}catch{return []}}
function saveSkippedRounds(){localStorage.setItem('fiscaliza-docente-skipped-rounds',JSON.stringify(state.skippedRounds))}
function roundKey(x){return [x.date,x.id].map(v=>String(v||'').trim()).join('|')}
function skipCurrentRound(){const current=orderedPendingRowsForDate(state.date)[0];if(!current)return null;const key=roundKey(current);if(!state.skippedRounds.includes(key)){state.skippedRounds.push(key);saveSkippedRounds();}return nextRonda();}
function clearSkippedForDate(date){state.skippedRounds=state.skippedRounds.filter(k=>!k.startsWith(String(date)+'|'));saveSkippedRounds();}
function restoreSkippedRound(key){state.skippedRounds=state.skippedRounds.filter(k=>k!==key);saveSkippedRounds();}
function roomProgress(x){const checks=normalizeRoomChecks(x);const done=checks.filter(c=>c.done).length;const pending=checks.filter(c=>!c.done);const followUps=checks.filter(c=>c.followUpPending&&!String(c.presentTeacher||'').trim()&&!String(c.followUpTeacher||'').trim()&&!c.followUpConcludedWithoutTeacher);return {checks,done,total:checks.length,pending,followUps,complete:done===checks.length};}
function roundIsPending(x){return !roomProgress(x).complete;}
function roundNeedsFollowUp(x){return roomProgress(x).followUps.some(c=>!String(c.presentTeacher||'').trim()&&!String(c.followUpTeacher||'').trim()&&!c.followUpConcludedWithoutTeacher);}
function roomStatusSummary(x){const statuses=roomProgress(x).checks.map(c=>c.status).filter(Boolean);if(!statuses.length)return null;if(new Set(statuses).size===1)return statuses[0];return 'Fiscalização concluída';}
function populateTeachers(){
  // A escala pode armazenar vários docentes no mesmo registro, separados por barra ou ponto e vírgula.
  // No campo Professor presente, cada docente deve aparecer como opção individual.
  const splitTeacherNames=value=>String(value||'').split(/\s*\/\s*|\s*;\s*|\s*\|\s*|\s*\n\s*/).map(name=>canonicalTeacher(name.trim())).filter(Boolean);
  const names=[...state.schedule.flatMap(x=>[...splitTeacherNames(x.scheduledTeacher),...splitTeacherNames(x.presentTeacher)]),...state.inspections.flatMap(x=>[...splitTeacherNames(x.scheduledTeacher),...splitTeacherNames(x.presentTeacher),...splitTeacherNames(x.assignedName)]),...INITIAL_DATA.schedule.flatMap(x=>splitTeacherNames(x.scheduledTeacher))];
  $('#teacherList').innerHTML=[...unique(names).map(n=>`<option value="${esc(n)}"></option>`),'<option value="Professor não identificado"></option>'].join('');
}
function render(){try{$('#todayText').textContent=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});const fn={dashboard:dashboard,ronda:ronda,escala:escala,historico:historico,professores:professores,ficha:ficha,salas:salas,relatorios:relatorios,config:config}[state.view];$('#view').innerHTML=fn();if(state.view==='config')updateCloudStatus();}catch(err){console.error(err);showError('Não foi possível renderizar esta tela.');}}
let liveClockTimer=setInterval(()=>{if(state.view==='ronda'||state.view==='dashboard')render();},30000);
function showError(msg){$('#view').innerHTML=`<div class="card empty"><strong>O aplicativo encontrou um erro.</strong><p>${esc(msg)}</p><button class="btn primary" onclick="location.reload()">Recarregar aplicativo</button></div>`}
function pageHead(title,text,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${text}</p></div><div class="toolbar">${actions}</div></div>`}
function badge(s){return `<span class="badge ${statusClass(s)}">${esc(s||'Pendente')}</span>`}
function metric(label,n,sub){return `<article class="metric"><span class="label">${label}</span><strong>${n}</strong><small>${sub}</small></article>`}
function pendingRowsForDate(date){const dayRows=state.schedule.filter(x=>x.date===date);const afternoonToday=date===todayISO()&&timeToMinutes(deviceTime())>=12*60;const morningCheckedNoClass=new Set(dayRows.filter(x=>x.unregisteredRoom&&roomShift(x)==='manha'&&roomProgress(x).complete).map(x=>normRoomForMatch(x.room)));const rows=dayRows.filter(x=>roundIsPending(x)&&!state.skippedRounds.includes(roundKey(x))&&!(afternoonToday&&roomShift(x)==='manha')&&!(x.unregisteredRoom&&roomShift(x)==='tarde'&&morningCheckedNoClass.has(normRoomForMatch(x.room)))).sort((a,b)=>Number(!!a.unregisteredRoom)-Number(!!b.unregisteredRoom)||String(a.start||'99:99').localeCompare(String(b.start||'99:99'))||String(a.room||'').localeCompare(String(b.room||''),'pt-BR')||String(a.scheduledTeacher||'').localeCompare(String(b.scheduledTeacher||''),'pt-BR'));const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[–—−]/g,'-').toLowerCase().replace(/\s+/g,' ').trim();const seen=new Set();return rows.filter(x=>{const k=[x.date,x.start,x.end,x.period,x.room,x.scheduledTeacher,x.subject].map(norm).join('|');if(seen.has(k))return false;seen.add(k);return true;});}
function sortRoundRows(rows){return [...rows].sort((a,b)=>Number(!!a.unregisteredRoom)-Number(!!b.unregisteredRoom)||(rondaTiming(a).key==='overdue'?-1:0)-(rondaTiming(b).key==='overdue'?-1:0)||String(a.start||'99:99').localeCompare(String(b.start||'99:99'))||String(a.room||'').localeCompare(String(b.room||''),'pt-BR'));}
function orderedPendingRowsForDate(date){return sortRoundRows(pendingRowsForDate(date));}
function rondaGroups(rows){return rows.map(x=>[x]).sort((a,b)=>String(a[0]?.start||'99:99').localeCompare(String(b[0]?.start||'99:99'))||String(a[0]?.room||'').localeCompare(String(b[0]?.room||''),'pt-BR'));}
function nextRonda(){const base=state.date||todayISO();const dates=[...new Set(state.schedule.map(x=>String(x.date||'')).filter(d=>d>=base))].sort();for(const date of dates){const found=orderedPendingRowsForDate(date)[0];if(found)return found;}return null;}
function followUpRowsForDate(date){return state.schedule.filter(x=>x.date===date&&roundNeedsFollowUp(x)).sort((a,b)=>String(a.start||'99:99').localeCompare(String(b.start||'99:99')));}
function dashboard(){
  // Painel calculado a partir das aulas e das salas registradas na Ronda.
  // A escala serve apenas como cadastro das aulas; o status vem de roomChecks.
  const selectedDate=state.date||todayISO();
  const aulas=state.schedule.filter(x=>!x.unregisteredRoom);
  const dateRows=aulas.filter(x=>String(x.date||'')===selectedDate);
  const checksFor=rows=>rows.flatMap(x=>roomProgress(x).checks.map(c=>({...c,_round:x}))).filter(c=>c.room);
  const selectedChecks=checksFor(dateRows);
  const doneChecks=selectedChecks.filter(c=>c.done&&c.status);
  const pendingChecks=selectedChecks.filter(c=>!c.done);
  const countStatus=(status)=>doneChecks.filter(c=>String(c.status||'').toLowerCase()===status.toLowerCase()).length;
  const present=countStatus('Presente');
  const late=countStatus('Atraso');
  const substitute=countStatus('Substituição');
  const absence=doneChecks.filter(c=>['Falta','Professor não localizado'].includes(c.status)).length;
  const justified=countStatus('Justificada');
  const other=Math.max(0,doneChecks.length-present-late-substitute-absence-justified);
  const coverage=selectedChecks.length?Math.round(doneChecks.length/selectedChecks.length*100):0;
  const totalAulas=dateRows.length;
  const completeAulas=dateRows.filter(x=>roomProgress(x).complete).length;
  const nextCandidates=aulas.filter(x=>String(x.date||'')>=todayISO()&&!roomProgress(x).complete&&!state.skippedRounds.includes(roundKey(x))).sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.start||'99:99').localeCompare(String(b.start||'99:99')));
  const next=nextCandidates[0]||null;
  const timing=next?rondaTiming(next):null;
  const statusPalette=[['Presente',present,'#16865b'],['Atraso',late,'#d78b18'],['Substituição',substitute,'#536bd8'],['Falta / não localizado',absence,'#d64c58'],['Justificada',justified,'#8065c9'],['Outras situações',other,'#8292a3']];
  let cursor=0; const totalDone=doneChecks.length;
  const gradient=totalDone?`conic-gradient(${statusPalette.map(([label,n,color])=>{const from=cursor;cursor+=n/totalDone*100;return `${color} ${from}% ${cursor}%`;}).join(',')})`:'conic-gradient(#e8edf2 0% 100%)';
  const trend=[]; const anchor=new Date(selectedDate+'T00:00:00');
  for(let i=6;i>=0;i--){const d=new Date(anchor);d.setDate(anchor.getDate()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const dayRows=aulas.filter(x=>String(x.date||'')===key);const dayChecks=checksFor(dayRows).filter(c=>c.done&&c.status);trend.push({key,label:d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.',''),total:dayChecks.length,present:dayChecks.filter(c=>c.status==='Presente').length,occurrences:dayChecks.filter(c=>c.status!=='Presente').length});}
  const maxTrend=Math.max(1,...trend.map(x=>x.total));
  const trendHtml=trend.map(d=>`<div class="exec-trend-col" title="${fmtDate(d.key)}: ${d.total} fiscalização(ões)"><div class="exec-trend-total">${d.total}</div><div class="exec-trend-bar"><i class="exec-trend-presence" style="height:${d.total?d.present/maxTrend*100:0}%"></i><i class="exec-trend-occurrence" style="height:${d.total?d.occurrences/maxTrend*100:0}%"></i></div><span>${esc(d.label)}</span></div>`).join('');
  const recent=checksFor(aulas).filter(c=>c.done&&c.status).sort((a,b)=>String(b._round.date||'').localeCompare(String(a._round.date||''))||String(b.checkedTime||'').localeCompare(String(a.checkedTime||''))).slice(0,7);
  const nextCard=next?`<section class="exec-next ${timing?.key==='overdue'?'is-overdue':''}"><div class="exec-next-icon">${timing?.key==='overdue'?'!':'↗'}</div><div class="exec-next-copy"><span class="exec-eyebrow">${timing?.key==='overdue'?'RONDA EM ATRASO':'PRÓXIMA AULA A FISCALIZAR'}</span><h2>${esc(next.room||'Sala não definida')} <span>${esc(next.start||'--:--')}–${esc(next.end||'--:--')}</span></h2><p>${esc((next.subject||'Disciplina não informada').replace(/\n/g,' • '))} · ${esc(next.scheduledTeacher||'Professor não informado')}</p><small>${fmtDate(next.date)} · ${roomProgress(next).done}/${roomProgress(next).total} sala(s) fiscalizada(s)</small></div><button class="btn primary" data-next-ronda>Continuar ronda <span aria-hidden="true">→</span></button></section>`:`<section class="exec-next exec-next-empty"><div class="exec-next-icon">✓</div><div class="exec-next-copy"><span class="exec-eyebrow">FILA DE RONDAS</span><h2>Não há aulas pendentes para fiscalizar</h2><p>Quando houver uma aula em aberto na Ronda, ela aparecerá aqui.</p></div><button class="btn ghost" data-go="ronda">Abrir Rondas →</button></section>`;
  const statusLegend=statusPalette.map(([label,n,color])=>`<div class="exec-legend-row"><i style="background:${color}"></i><span>${esc(label)}</span><strong>${n}</strong><small>${totalDone?Math.round(n/totalDone*100):0}%</small></div>`).join('');
  const recentHtml=recent.length?recent.map(c=>`<div class="exec-activity-row"><div class="exec-activity-dot ${statusClass(c.status)}"></div><div class="exec-activity-main"><strong>${esc(c._round.scheduledTeacher||c.presentTeacher||'Professor não informado')}</strong><span>${esc(c._round.subject||'Disciplina não informada')} · Sala ${esc(c.room||'—')}</span></div><div class="exec-activity-meta">${badge(c.status)}<small>${fmtDate(c._round.date)}${c.checkedTime?' · '+esc(c.checkedTime):''}</small></div></div>`).join(''):`<div class="exec-empty"><span>▤</span><strong>Nenhuma fiscalização registrada</strong><p>As atividades concluídas na Ronda aparecerão nesta lista automaticamente.</p></div>`;
  return `<div class="exec-dashboard">
    <header class="exec-heading"><div><span class="exec-eyebrow">UNIG · MEDICINA · NOVA IGUAÇU</span><h1>Painel de controle</h1><p>Visão operacional das aulas e fiscalizações registradas na Ronda.</p></div><div class="exec-date-control"><label for="dashboardDate">Data de referência</label><input id="dashboardDate" class="control" type="date" data-dashboard-date value="${esc(selectedDate)}"></div></header>
    ${nextCard}
    <section class="exec-kpis">
      <article class="exec-kpi"><div class="exec-kpi-top"><span>Aulas na Ronda</span><i class="exec-kpi-icon blue">▦</i></div><strong>${totalAulas}</strong><small>${completeAulas} aula(s) com todas as salas fiscalizadas</small><div class="exec-kpi-foot"><span style="width:${totalAulas?completeAulas/totalAulas*100:0}%"></span></div></article>
      <article class="exec-kpi"><div class="exec-kpi-top"><span>Salas fiscalizadas</span><i class="exec-kpi-icon green">✓</i></div><strong>${doneChecks.length}</strong><small>De ${selectedChecks.length} sala(s) previstas na Ronda</small><div class="exec-kpi-foot"><span style="width:${coverage}%"></span></div></article>
      <article class="exec-kpi"><div class="exec-kpi-top"><span>Presenças</span><i class="exec-kpi-icon green">●</i></div><strong>${present}</strong><small>${totalDone?Math.round(present/totalDone*100):0}% das fiscalizações concluídas</small><div class="exec-kpi-accent green"></div></article>
      <article class="exec-kpi"><div class="exec-kpi-top"><span>Ocorrências</span><i class="exec-kpi-icon amber">!</i></div><strong>${doneChecks.length-present}</strong><small>Atrasos, faltas e demais situações</small><div class="exec-kpi-accent amber"></div></article>
    </section>
    <div class="exec-charts-grid">
      <section class="card panel exec-chart-card"><div class="exec-section-head"><div><span class="exec-eyebrow">DISTRIBUIÇÃO</span><h2>Situações registradas</h2><p>Somente fiscalizações concluídas na Ronda de ${fmtDate(selectedDate)}.</p></div><span class="exec-total-pill">${totalDone} registros</span></div><div class="exec-donut-layout"><div class="exec-donut" style="background:${gradient}"><div><strong>${totalDone}</strong><span>fiscalizações</span></div></div><div class="exec-legend">${statusLegend}</div></div></section>
      <section class="card panel exec-chart-card"><div class="exec-section-head"><div><span class="exec-eyebrow">ÚLTIMOS 7 DIAS</span><h2>Volume de fiscalizações</h2><p>Comparativo entre presenças e outras situações registradas.</p></div><span class="exec-chart-key"><i></i> Presenças <i class="amber"></i> Ocorrências</span></div><div class="exec-trend-chart">${trendHtml}</div><div class="exec-trend-axis"><span>${fmtDate(trend[0].key)}</span><span>${fmtDate(trend[6].key)}</span></div></section>
    </div>
    <div class="exec-bottom-grid"><section class="card panel exec-activity-card"><div class="exec-section-head"><div><span class="exec-eyebrow">ATIVIDADE RECENTE</span><h2>Últimas fiscalizações</h2><p>Dados reais registrados nas aulas da Ronda.</p></div><button class="btn ghost small" data-go="historico">Ver histórico →</button></div><div class="exec-activity-list">${recentHtml}</div></section>
      <section class="card panel exec-day-card"><div class="exec-section-head"><div><span class="exec-eyebrow">ACOMPANHAMENTO DIÁRIO</span><h2>Progresso da Ronda</h2><p>${fmtDate(selectedDate)}</p></div></div><div class="exec-day-progress"><div class="exec-day-progress-ring" style="--progress:${coverage*3.6}deg"><div><strong>${coverage}%</strong><span>concluído</span></div></div><div class="exec-day-summary"><div><span>Salas fiscalizadas</span><strong>${doneChecks.length}</strong></div><div><span>Salas restantes</span><strong>${pendingChecks.length}</strong></div><div><span>Aulas concluídas</span><strong>${completeAulas} / ${totalAulas}</strong></div></div></div><button class="btn primary exec-open-rounds" data-go="ronda">Abrir Rondas <span aria-hidden="true">→</span></button></section></div>
  </div>`;
}
function teacherAnalytics(){
  const rowsByName=new Map();
  const splitNames=value=>[...new Set(String(value||'').split(/\s*\/\s*|\s*;\s*|\s*\|\s*|\s*,\s*|\s*\n\s*/).map(v=>canonicalTeacher(v.trim())).filter(Boolean))];
  const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[–—−]/g,'-').toLowerCase().replace(/\s+/g,' ').trim();
  const addPresent=(value,row)=>{
    for(const name of splitNames(value)){
      if(!rowsByName.has(name))rowsByName.set(name,[]);
      rowsByName.get(name).push({...row,teacherFicha:name});
    }
  };
  // A ficha pertence somente ao docente efetivamente identificado no campo Professor presente.
  // Docente escalado, isoladamente, nunca gera ficha nem ocorrência individual.
  for(const i of state.inspections){
    if(!i.status||i.excludeFromTeacherFicha||!i.presentTeacher||['Professor não identificado','Sala vazia'].includes(i.status))continue;
    addPresent(i.presentTeacher,{...i,scheduledTeacher:i.scheduledTeacher||'',plannedRoom:i.plannedRoom||i.presentRoom||'',source:'Histórico'});
  }
  for(const x of state.schedule){
    for(const c of normalizeRoomChecks(x).filter(c=>c.done&&c.status&&!c.excludeFromTeacherFicha)){
      if(['Professor não identificado','Sala vazia'].includes(c.status)||!String(c.presentTeacher||x.presentTeacher||'').trim())continue;
      const row={...x,status:c.status,scheduledTeacher:x.scheduledTeacher||'',presentTeacher:c.presentTeacher||x.presentTeacher||'',plannedRoom:c.room,presentRoom:c.presentRoom||c.room,checkedTime:c.checkedTime||x.checkedTime||'',realTime:'',notes:c.notes||x.notes||'',source:'Ronda',scheduleId:x.id};
      addPresent(row.presentTeacher,row);
    }
  }
  return [...rowsByName.entries()].map(([name,all])=>{
    const seen=new Map();
    for(const x of all){
      if(!x?.status)continue;
      // Mesma fiscalização pode existir na tabela de ronda e em inspeções sincronizadas.
      // A chave estável de ronda/sala evita contar a duplicata duas vezes; sem ID, usa campos funcionais.
      const key=[x.scheduleId||x.id||'',x.date||'',norm(x.presentTeacher),norm(x.status),norm(x.presentRoom||x.plannedRoom),norm(x.checkedTime),norm(x.subject),norm(x.notes)].join('|');
      if(!seen.has(key))seen.set(key,x);
      else { const old=seen.get(key); seen.set(key,{...old,...x,notes:old.notes||x.notes,checkedTime:old.checkedTime||x.checkedTime}); }
    }
    const rows=[...seen.values()].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.checkedTime||'').localeCompare(String(a.checkedTime||'')));
    const done=rows;
    const occurrences=done.filter(x=>x.status!=='Presente').length;
    const present=done.filter(x=>x.status==='Presente').length;
    const late=done.filter(x=>x.status==='Atraso').length;
    const absences=done.filter(x=>['Falta','Professor não localizado'].includes(x.status)||String(x.status).toLowerCase().includes('ausente')).length;
    const rate=done.length?Math.round(present/done.length*100):0;
    return {name,rows,done,occurrences,present,late,absences,rate};
  }).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
}
function teacherRows(name){return teacherAnalytics().find(x=>x.name===name)?.rows||[];}
function teacherStatus(a){
  if(!a || a.done.length===0) return {label:'Sem registros',className:'monitor',reason:'Ainda não há nenhuma situação fiscalizada registrada para este professor. Isso não representa uma avaliação negativa.'};
  if(a.absences>0) return {label:'Atenção — faltas registradas',className:'attention',reason:`Há ${a.absences} registro(s) de falta ou professor não localizado. É necessário verificar as ocorrências.`};
  if(a.late>a.present) return {label:'Regularidade baixa',className:'attention',reason:`Foram registrados ${a.late} atraso(s) para ${a.present} presença(s). Os atrasos superam as presenças.`};
  if(a.present>=2*Math.max(1,a.late) && a.present>0) return {label:'Bom desempenho',className:'good',reason:`Há ${a.present} presença(s) e ${a.late} atraso(s), com pelo menos o dobro de presenças em relação aos atrasos e sem faltas registradas.`};
  if(a.present>0 && a.late>0) return {label:'Desempenho intermediário',className:'watch',reason:`Há ${a.present} presença(s) e ${a.late} atraso(s). Vale acompanhar a regularidade nas próximas fiscalizações.`};
  if(a.present>0 && a.late===0) return {label:'Bom desempenho',className:'good',reason:'As situações registradas são presenças, sem atrasos ou faltas registrados.'};
  return {label:'Acompanhamento',className:'watch',reason:'Há situações registradas, mas ainda não há presenças suficientes para classificar o desempenho como bom.'};
}
function ficha(){
  const name=state.selectedTeacher; const analytics=teacherAnalytics().find(x=>x.name===name);
  if(!analytics) return `${pageHead('Ficha do professor','A ficha é criada somente quando o docente está identificado no campo “Professor presente”.',`<button class="btn ghost" data-back-professores>← Voltar aos professores</button>`)}<div class="empty card">Nenhum registro de professor presente encontrado. Registros em que o docente aparece apenas como escalado não geram ficha.</div>`;
  const s=teacherStatus(analytics), rows=analytics.rows;
  const byStatus=unique(rows.map(x=>x.status)).map(status=>[status,rows.filter(x=>x.status===status).length]);
  const rooms=unique(rows.map(x=>`${x.subject||'Disciplina não informada'} • ${x.presentRoom||x.plannedRoom||x.room||'Sala não informada'}`));
  return `${pageHead('Ficha individual do professor','Dados consolidados exclusivamente das fiscalizações em que o docente consta como professor presente.',`<button class="btn ghost" data-back-professores>← Todos os professores</button>`)}
  <section class="teacher-profile teacher-profile-v2 card"><div class="profile-main"><div class="avatar">${esc(name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</div><div><span class="muted">FICHA INDIVIDUAL · PROFESSOR PRESENTE</span><h2>${esc(name)}</h2><p>${rows.length} fiscalização(ões) válida(s) · duplicatas consolidadas</p></div></div><div class="profile-status ${s.className}"><strong>${s.label}</strong><span>${s.reason}</span></div></section>
  <section class="metrics profile-metrics">${metric('Fiscalizações',rows.length,'registros únicos')}${metric('Presenças',analytics.present,'situação presente')}${metric('Atrasos',analytics.late,'situação atraso')}${metric('Outras ocorrências',analytics.occurrences-analytics.late,'demais situações registradas')}</section>
  <div class="dashboard-grid teacher-info-grid"><section class="card panel"><div class="panel-head"><h2>Distribuição das situações</h2><span class="muted">Somente registros válidos</span></div>${byStatus.length?byStatus.map(([st,n])=>`<div class="kpi"><span>${esc(st)}</span>${badge(st)}<strong style="margin-left:auto">${n}</strong></div>`).join(''):'<div class="empty">Nenhuma situação registrada.</div>'}</section><section class="card panel"><div class="panel-head"><h2>Disciplinas e salas</h2></div>${rooms.length?rooms.map(v=>`<div class="teacher-info-row"><span>${esc(v)}</span></div>`).join(''):'<div class="empty">Sem dados disponíveis.</div>'}</section></div>
  <section class="card panel teacher-records"><div class="panel-head"><div><h2>Registros de fiscalização</h2><span class="muted">Cada cartão corresponde a uma fiscalização única; o docente precisa constar como professor presente.</span></div><span class="badge other">${rows.length} registros</span></div><div class="teacher-record-list">${rows.length?rows.map(x=>`<article class="teacher-record"><div class="teacher-record-top"><div><span class="teacher-record-date">${esc(fmtDate(x.date))}</span><h3>${esc(x.subject||'Disciplina não informada')}</h3></div>${badge(x.status)}</div><div class="teacher-record-fields"><div><small>Professor presente</small><strong>${esc(x.presentTeacher||name)}</strong></div><div><small>Professor escalado</small><strong>${esc(x.scheduledTeacher||'—')}</strong></div><div><small>Horário fiscalizado</small><strong>${esc(x.checkedTime||'Não informado')}</strong></div><div><small>Período</small><strong>${esc(x.period||'—')}</strong></div><div><small>Sala prevista</small><strong>${esc(x.plannedRoom||x.room||'—')}</strong></div><div><small>Sala fiscalizada</small><strong>${esc(x.presentRoom||x.plannedRoom||x.room||'—')}</strong></div><div><small>Origem</small><strong>${esc(x.source||'Fiscalização')}</strong></div></div>${x.notes?`<div class="teacher-record-notes"><small>Observações</small><p>${esc(x.notes)}</p></div>`:''}</article>`).join(''):'<div class="empty">Nenhum registro encontrado.</div>'}</div></section>`;
}
function monthlyAnalytics(month){
  const months=[]; const base=new Date(month+'-01T00:00:00'); for(let i=5;i>=0;i--){const d=new Date(base.getFullYear(),base.getMonth()-i,1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const total=state.schedule.filter(x=>String(x.date||'').startsWith(key)&&x.status).length;months.push({key,total,label:d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','')});} const max=Math.max(1,...months.map(x=>x.total)); return months.map(x=>({...x,max}));
}
function miniRow(x){const p=roomProgress(x);const label=p.complete?(p.followUps.length?'Retorno pendente':roomStatusSummary(x)):`${p.done}/${p.total} sala(s) fiscalizada(s)`;return `<div class="kpi"><div><strong>${esc(x.room||'Sala não definida')}</strong><div class="muted">${esc(x.start||'--:--')} — ${esc(x.end||'--:--')} • ${esc(x.period||'')}</div><small>${esc(label)}</small></div><div style="display:flex;align-items:center;gap:8px"><span class="badge ${p.complete?'present':'pending'}">${p.complete?(p.followUps.length?'Retorno':'Fiscalizado'):'Pendente'}</span><button class="btn small primary" data-inspect="${esc(x.id)}">${p.complete?'Abrir':'Fiscalizar'}</button></div></div>`}
function roomCardLine(x,c){return `<div class="room-check-row ${c.done?'is-done':'is-pending'}"><div><strong>${esc(c.room)}</strong><small>${c.done?esc(c.status||'Fiscalizada'):'Ainda não fiscalizada'}${c.followUpPending?' • Retorno necessário':''}</small></div><button class="btn ${c.followUpPending?'primary':'ghost'} small" data-inspect="${esc(x.id)}" data-inspect-room="${esc(c.room)}" data-inspect-mode="${c.followUpPending?'followup':'normal'}">${c.followUpPending?'Retorno':'Abrir'}</button></div>`}
function ronda(){
  const rows=state.schedule.filter(x=>x.date===state.date);
  const pending=orderedPendingRowsForDate(state.date); const groups=pending.map(x=>[x]);
  const skippedRows=state.schedule.filter(x=>x.date===state.date&&roundIsPending(x)&&state.skippedRounds.includes(roundKey(x))); const skippedGroups=rondaGroups(skippedRows);
  const followUps=followUpRowsForDate(state.date);
  const completed=rows.filter(x=>roomProgress(x).complete).length; const selectedToday=state.date===todayISO();
  const overdueGroups=groups.filter(g=>rondaTiming(g[0]).key==='overdue'); const activeGroups=groups.filter(g=>['future','live'].includes(rondaTiming(g[0]).key)); const orderedGroups=groups;
  const current=orderedGroups[0]?.[0]; const currentTiming=current?rondaTiming(current):null; const nowText=deviceTime(); const overdueCount=overdueGroups.length;
  const skippedHtml=skippedGroups.length?`<section class="card panel skipped-rounds"><div class="panel-head"><div><h2>Rondas adiadas</h2><span class="muted">Você pode voltar qualquer uma para a fila.</span></div><button class="btn ghost small" data-clear-skips>Reabrir todas</button></div><div class="route-list">${skippedGroups.map(group=>{const x=group[0],p=roomProgress(x);return `<article class="route-item"><div class="route-index">↩</div><div class="route-info"><strong>${esc(x.room||'Sala não definida')}</strong><span>${esc(x.unregisteredRoom?'Sem aula registrada — verificar se há aula':`${x.start||'--:--'} — ${x.end||'--:--'} • ${x.period||''}`)}</span><small>${p.done}/${p.total} sala(s) fiscalizada(s) • ${esc((x.subject||'').replace(/\n/g,' • '))}</small></div><button class="btn primary small" data-restore-skip="${esc(roundKey(x))}">Voltar para fila</button></article>`}).join('')}</div></section>`:'';
  const followUpHtml=followUps.length?`<section class="card panel followup-panel"><div class="panel-head"><div><h2>Retornos necessários</h2><span class="muted">Professor marcado como atraso precisa ser revisado.</span></div><strong class="badge late">${followUps.reduce((n,x)=>n+roomProgress(x).followUps.length,0)}</strong></div><div class="route-list">${followUps.flatMap(x=>roomProgress(x).followUps.map(c=>`<article class="route-item"><div class="route-index">↻</div><div class="route-info"><strong>${esc(c.room)}</strong><span>${esc(x.start||'--:--')} — ${esc(x.end||'--:--')} • ${esc(x.period||'')}</span><small>${esc(x.scheduledTeacher||'Professor escalado')} • Atraso registrado${c.checkedTime?' às '+esc(c.checkedTime):''}</small></div><div class="followup-actions"><button class="btn primary small" data-inspect="${esc(x.id)}" data-inspect-room="${esc(c.room)}" data-inspect-mode="followup">Verificar chegada</button><button class="btn ghost small" data-conclude-followup="${esc(x.id)}" data-room="${esc(c.room)}">Concluir ronda</button></div></article>`)).join('')}</div></section>`:'';
  const completedRooms=rows.flatMap(x=>roomProgress(x).checks.filter(c=>c.done).map(c=>({x,c})));
  const completedHtml=completedRooms.length?`<section class="card panel completed-rounds"><div class="panel-head"><div><h2>Já fiscalizadas</h2><span class="muted">Cada sala aparece aqui assim que for conferida.</span></div><strong>${completedRooms.length} sala(s)</strong></div><div class="route-list">${completedRooms.map(({x,c})=>`<article class="route-item"><div class="route-index">✓</div><div class="route-info"><strong>${esc(c.room)}</strong><span>${esc(x.start||'--:--')} — ${esc(x.end||'--:--')} • ${esc(x.scheduledTeacher||'Professor não informado')}</span><small>${esc(c.status||'Fiscalizado')}${c.followUpPending?' • retorno necessário':''}${c.presentTeacher?' • '+esc(c.presentTeacher):''}</small></div><button class="btn ghost small" data-inspect="${esc(x.id)}" data-inspect-mode="${c.followUpPending?'followup':'normal'}" data-inspect-room="${esc(c.room)}">${c.followUpPending?'Verificar chegada':'Abrir'}</button></article>`).join('')}</div></section>`:`<section class="card panel"><div class="empty"><strong>Nenhuma sala fiscalizada ainda.</strong><p>As salas concluídas aparecerão aqui após o registro.</p></div></section>`;
  const callout=currentTiming?.key==='overdue'?'⚠ Ronda atrasada — mais de 10 min':currentTiming?.key==='live'?'✓ Horário da aula — faça a ronda agora':'✓ Próxima aula pendente';
  return `${pageHead('Rondas','Cada sala é controlada separadamente. A aula só sai da fila quando todas as salas forem fiscalizadas.',`<span class="device-clock compact">Agora: <strong>${nowText}</strong></span><input class="control" type="date" id="rondaDate" value="${state.date}"><button class="btn ghost" data-new-class>+ Nova aula</button><button class="btn primary" data-next-ronda>Próxima</button>`)}${selectedToday?`<div class="ronda-live card"><div><strong>Horário do dispositivo</strong><span>${nowText}</span></div><div><strong>${overdueCount}</strong><span>ronda(s) atrasada(s)</span></div><div><strong>${orderedGroups.length}</strong><span>ronda(s) pendente(s)</span></div></div>`:''}<div class="ronda-summary"><div><strong>${pending.length}</strong><span>rondas pendentes</span></div><div><strong>${completed}</strong><span>salas/rondas completas</span></div><div><strong>${rows.length}</strong><span>registros no dia</span></div></div>${followUpHtml}${skippedHtml}${current?`<section class="next-focus card ${currentTiming.key==='overdue'?'is-overdue':''}"><div class="next-round-label">${currentTiming.label}</div><div class="next-focus-grid"><div><span class="status-callout ${currentTiming.className}">${callout}</span><span class="muted">${esc(current.start||'--:--')} — ${esc(current.end||'--:--')}</span><h2>${esc(current.room||'Sala não definida')}</h2><p>${esc((current.subject||'').replace(/\n/g,' • '))}</p><div class="teacher-stack"><span>${esc(current.unregisteredRoom?'Sem professor escalado — sala sem aula registrada':(current.scheduledTeacher||'Professor não informado'))}</span></div><div class="room-check-list">${roomProgress(current).checks.map(c=>roomCardLine(current,c)).join('')}</div></div><div style="display:flex;flex-direction:column;gap:8px;align-items:stretch"><button class="btn ghost small" data-skip-ronda>Passar para próxima ronda</button><button class="btn ghost small danger" data-delete-round="${esc(current.id)}">Excluir ronda</button></div></div></section>`:''}${orderedGroups.length>1?`<div class="section-caption"><strong>${overdueGroups.length>0?'Fila de rondas':'Próximas salas'}</strong><span>${selectedToday?'Ordenadas pelo horário do dispositivo':'Em ordem de horário'}</span></div><div class="route-list">${orderedGroups.slice(1).map((group,i)=>{const x=group[0],t=rondaTiming(x),p=roomProgress(x);return `<article class="route-item ${t.key==='overdue'?'is-overdue':''}"><div class="route-index">${i+2}</div><div class="route-info"><strong>${esc(x.room||'Sala não definida')}</strong><span>${esc(x.unregisteredRoom?'Sem aula registrada — verificar se há aula':`${x.start||'--:--'} — ${x.end||'--:--'} • ${x.period||''}`)}</span><small>${p.done}/${p.total} sala(s) fiscalizada(s)${p.followUps.length?' • '+p.followUps.length+' retorno(s)':''}</small></div><span class="route-status ${t.className}">${t.label}</span><button class="btn ghost small" data-inspect="${esc(x.id)}">Abrir</button><button class="btn ghost small danger" data-delete-round="${esc(x.id)}">Excluir</button></article>`}).join('')}</div>`:`<div class="card empty"><strong>${rows.length?'Nenhuma outra ronda na fila.':'Nenhuma aula encontrada nesta data.'}</strong><p>${rows.length?'As rondas adiadas ficam disponíveis para reabertura. Os retornos continuam no bloco “Retornos necessários”.':'Selecione outra data ou cadastre uma nova aula.'}</p></div>`}}`+completedHtml;
}
function escala(){
  let rows=[...state.schedule];
  if(state.date) rows=rows.filter(x=>x.date===state.date);
  if(state.search){const q=state.search.toLowerCase();rows=rows.filter(x=>[x.scheduledTeacher,x.room,x.subject,x.period].some(v=>String(v||'').toLowerCase().includes(q)))}
  if(state.status) rows=rows.filter(x=>x.status===state.status);
  return `${pageHead('Escala docente','Consulte a programação original e use os filtros para encontrar rapidamente uma aula.',`<input class="control" type="date" id="scaleDate" value="${state.date}"><input class="control" id="scaleSearch" value="${esc(state.search)}" placeholder="Buscar professor, sala..."><button class="btn primary" data-new-class>+ Nova aula</button>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Horário</th><th>Sala</th><th>Período</th><th>Professor escalado</th><th>Disciplina</th><th>Situação</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><strong>${esc(x.start||'')}</strong><br><span class="muted">${esc(x.end||'')}</span></td><td>${esc(x.room||'—')}</td><td>${esc(x.period||'—')}</td><td><strong>${esc(x.scheduledTeacher||'—')}</strong></td><td>${esc((x.subject||'').replace(/\n/g,' • '))}</td><td>${badge(x.status)}</td><td><button class="btn primary small" data-inspect="${esc(x.id)}">Fiscalizar</button></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty"><strong>Nenhum registro encontrado.</strong></div></td></tr>`}</tbody></table></div>`;
}
function historyRows(){
  const linkedScheduleIds=new Set(state.inspections.map(i=>String(i.scheduleId||'')).filter(Boolean));
  const merged=[
    ...state.schedule.filter(x=>!linkedScheduleIds.has(String(x.id))&&(x.status||(Array.isArray(x.roomChecks)&&x.roomChecks.some(c=>c.done&&c.status)))).map(x=>{
      const checks=normalizeRoomChecks(x);
      const doneChecks=checks.filter(c=>c.done&&c.status);
      return {...x,date:x.date,scheduledTeacher:x.scheduledTeacher,presentTeacher:x.presentTeacher||doneChecks.map(c=>c.presentTeacher).filter(Boolean).join(' / '),plannedRoom:x.room,presentRoom:x.presentRoom||doneChecks.map(c=>c.presentRoom||c.room).filter(Boolean).join(' / '),status:x.status||(doneChecks.length===1?doneChecks[0].status:roomStatusSummary(x)),notes:x.notes||doneChecks.map(c=>c.notes).filter(Boolean).join(' • '),checkedTime:x.checkedTime||doneChecks.map(c=>c.checkedTime).filter(Boolean).join(' / '),plannedTime:`${x.start||'—'}${x.end?' – '+x.end:''}`,createdAt:x.updatedAt||x.createdAt||x.date+'T00:00:00',source:x.source||'Ronda',scheduleId:x.id,roomChecks:checks,period:x.period,subject:x.subject,recordStatus:x.recordStatus,followUpPending:x.followUpPending};
    }),
    ...state.inspections.map(x=>({...x,source:x.source||'Histórico',plannedTime:x.plannedTime||x.plannedTimeRange||'',plannedRoom:x.plannedRoom||x.room||''}))
  ];
  const seen=new Set();
  return merged.filter(x=>{
    const key=[x.date,x.scheduledTeacher||x.assignedName,x.presentTeacher,x.presentRoom||x.plannedRoom,x.status,x.subject,x.checkedTime,x.notes].map(v=>String(v||'').trim()).join('|');
    if(seen.has(key)) return false; seen.add(key); return true;
  }).filter(x=>!state.historyMonth||String(x.date||'').startsWith(state.historyMonth))
    .filter(x=>!state.historyStatus||x.status===state.historyStatus||(x.roomChecks||[]).some(c=>c.status===state.historyStatus))
    .filter(x=>{if(!state.historySearch)return true;const q=state.historySearch.toLocaleLowerCase('pt-BR');return [x.date,x.scheduledTeacher,x.assignedName,x.presentTeacher,x.status,x.presentRoom,x.plannedRoom,x.subject,x.period,x.notes,x.source,x.checkedTime].concat((x.roomChecks||[]).flatMap(c=>[c.room,c.status,c.presentTeacher,c.notes,c.checkedTime])).some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(q));})
    .sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.checkedTime||'').localeCompare(String(a.checkedTime||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
}
function historico(){
  const allRows=historyRows();
  const statuses=unique(allRows.flatMap(x=>[x.status,...(x.roomChecks||[]).map(c=>c.status)]).filter(Boolean));
  const countStatus=s=>allRows.filter(x=>x.status===s||(x.roomChecks||[]).some(c=>c.status===s)).length;
  const dateTime=v=>{if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});};
  const recordCard=x=>{
    const checks=(x.roomChecks||[]).filter(c=>c.done||c.status||c.presentTeacher||c.checkedTime||c.notes);
    const room=x.presentRoom||x.plannedRoom||x.room||'—';
    const subject=String(x.subject||'').replace(/\n/g,' • ')||'—';
    const plannedTime=x.plannedTime||([x.start,x.end].filter(Boolean).join(' – '))||'—';
    const checkedTime=x.checkedTime||checks.map(c=>c.checkedTime).filter(Boolean).join(' / ')||'—';
    const status=x.status||(checks.find(c=>c.done&&c.status)||{}).status||'Fiscalizado';
    const teacher=x.scheduledTeacher||x.assignedName||'Não informado';
    const present=x.presentTeacher||checks.map(c=>c.presentTeacher).filter(Boolean).join(' / ')||'Não informado';
    const field=(label,value,extra='')=>`<div class="hr23-field ${extra}"><span>${label}</span><strong>${esc(value||'—')}</strong></div>`;
    const rooms=checks.length?`<section class="hr23-rooms"><div class="hr23-section-title"><span class="hr23-section-icon">⌂</span><div><strong>Detalhamento por sala</strong><small>${checks.length} sala(s) vinculada(s) a este registro</small></div></div><div class="hr23-room-grid">${checks.map(c=>`<article class="hr23-room"><div class="hr23-room-top"><strong>Sala ${esc(c.presentRoom||c.room||'—')}</strong>${badge(c.status|| (c.done?'Fiscalizada':'Não fiscalizada'))}</div><div class="hr23-room-lines"><div><span>Professor presente</span><strong>${esc(c.presentTeacher||'Não informado')}</strong></div><div><span>Horário fiscalizado</span><strong>${esc(c.checkedTime||'—')}</strong></div>${c.notes?`<div><span>Observação</span><strong>${esc(c.notes)}</strong></div>`:''}${c.followUpPending?'<span class="hr23-followup">Retorno necessário</span>':''}</div></article>`).join('')}</div></section>`:'';
    const searchText=[x.date,teacher,present,status,room,subject,x.period,x.notes,x.source,checkedTime,...checks.flatMap(c=>[c.room,c.status,c.presentTeacher,c.notes,c.checkedTime])].join(' ').toLocaleLowerCase('pt-BR');
    return `<article class="hr23-record" data-history-record data-search-text="${esc(searchText)}"><header class="hr23-record-head"><div class="hr23-date-mark"><span>DATA DA RONDA</span><strong>${esc(fmtDate(x.date))}</strong><small>${esc(x.day||'Registro de fiscalização')}</small></div><div class="hr23-status-block">${badge(status)}<span class="hr23-source">${esc(x.source||'Ronda')}</span></div></header><div class="hr23-people"><div class="hr23-person"><span class="hr23-label">PROFESSOR ESCALADO</span><strong>${esc(teacher)}</strong></div><div class="hr23-person"><span class="hr23-label">PROFESSOR PRESENTE</span><strong>${esc(present)}</strong></div></div><section class="hr23-section"><div class="hr23-section-title"><span class="hr23-section-icon">▤</span><div><strong>Informações da aula</strong><small>Dados vinculados à fiscalização</small></div></div><div class="hr23-fields">${field('Disciplina',subject)}${field('Período',x.period||'—')}${field('Sala prevista',x.plannedRoom||x.room||'—')}${field('Sala fiscalizada',room)}${field('Horário da aula',plannedTime)}${field('Horário fiscalizado',checkedTime,'hr23-highlight')}${field('Atualizado em',dateTime(x.updatedAt||x.createdAt))}${field('Estado do registro',x.recordStatus||'Fiscalização registrada')}${field('Origem',x.source||'Ronda')}</div></section>${rooms}<section class="hr23-notes"><span class="hr23-label">OBSERVAÇÕES</span><p>${esc(x.notes||'Nenhuma observação registrada.')}</p></section><footer class="hr23-actions"><small>${x.scheduleId?'Registro vinculado à Ronda':'Registro histórico'}${x.followUpPending?' · retorno pendente':''}</small><div>${x.scheduleId?`<button class="btn ghost small" data-edit-history="${esc(x.scheduleId)}">Editar registro</button>`:''}<button class="btn ghost small danger" data-delete-history="${esc(x.scheduleId||'')}" data-delete-history-inspection="${x.scheduleId?'':esc(x.id||'')}">Excluir</button></div></footer></article>`;
  };
  const list=allRows.length?`<div class="hr23-list">${allRows.map(recordCard).join('')}</div><div class="card empty history-search-empty" style="display:none"><strong>Nenhum registro corresponde à busca.</strong><p>Altere o termo pesquisado ou os filtros.</p></div>`:`<div class="hr23-empty"><div class="hr23-empty-icon">⌕</div><strong>Nenhum registro encontrado</strong><p>Altere o mês ou a situação para consultar outros registros.</p></div>`;
  return `${pageHead('Histórico','Consulte cada fiscalização em um registro completo. Os horários reais de início e término não são exibidos; o horário fiscalizado fica em destaque.',`<input class="control" type="month" id="historyMonth" value="${state.historyMonth}"><select class="control" id="historyStatus"><option value="">Todas as situações</option>${statuses.map(s=>`<option value="${esc(s)}" ${state.historyStatus===s?'selected':''}>${esc(s)}</option>`).join('')}</select><button class="btn ghost" data-new-class>+ Nova aula</button><button class="btn ghost" id="exportHistory">Exportar CSV</button>`)}<section class="hr23-toolbar"><div><span class="hr23-eyebrow">CONSULTA E RASTREABILIDADE</span><h2>Registros de fiscalização</h2><p>Informações completas, organizadas por registro e por sala.</p></div><label class="hr23-search"><span>Buscar no histórico</span><input class="control" id="historySearch" value="${esc(state.historySearch)}" placeholder="Professor, disciplina, sala, observação..."></label></section><div class="hr23-summary"><div><span>Registros encontrados</span><strong>${allRows.length}</strong><small>Após aplicar os filtros</small></div><div><span>Presenças</span><strong>${countStatus('Presente')}</strong><small>Fiscalizações registradas</small></div><div><span>Atrasos</span><strong>${countStatus('Atraso')}</strong><small>Ocorrências identificadas</small></div><div><span>Outras situações</span><strong>${allRows.filter(x=>x.status&& !['Presente','Atraso'].includes(x.status)).length}</strong><small>Demais registros</small></div></div><div class="hr23-results-head"><strong>Histórico detalhado</strong><span>${allRows.length} registro(s)</span></div>${list}`;
}
function historyRowsForMonth(month){return historyRowsWithoutFilter(month)}
function historyRowsWithoutFilter(month){const merged=[...state.schedule.filter(x=>x.status).map(x=>({date:x.date,scheduledTeacher:x.scheduledTeacher,presentTeacher:x.presentTeacher,plannedRoom:x.room,presentRoom:x.presentRoom,status:x.status,notes:x.notes,createdAt:x.createdAt||x.date+'T00:00:00',scheduleId:x.id})),...state.inspections.map(x=>({...x}))];const seen=new Set();return merged.filter(x=>{const key=[x.date,x.scheduledTeacher||x.assignedName,x.presentTeacher,x.presentRoom||x.plannedRoom,x.status,x.notes].map(v=>String(v||'').trim()).join('|');if(seen.has(key))return false;seen.add(key);return true;}).filter(x=>String(x.date||'').startsWith(month));}
function professores(){
  const analytics=teacherAnalytics();
  return `${pageHead('Professores','Cada docente possui uma ficha automática baseada nas fiscalizações registradas.',`<input class="control" id="teacherSearch" placeholder="Buscar professor...">`)}
  <section class="metrics">${metric('Docentes',analytics.length,'com histórico fiscalizado')}${metric('Regularidade alta',analytics.filter(x=>teacherStatus(x).className==='good').length,'indicador automático')}${metric('Acompanhamento',analytics.filter(x=>['watch','attention'].includes(teacherStatus(x).className)).length,'merecem consulta')}${metric('Registros',state.schedule.filter(x=>x.status).length,'fiscalizações')}</section>
  <div class="list-cards" id="teacherCards">${analytics.length?analytics.map(x=>{const s=teacherStatus(x);return `<button class="teacher-card teacher-card-btn" data-teacher="${esc(x.name)}" data-name="${esc(x.name.toLowerCase())}"><div class="teacher-card-main"><strong>${esc(x.name)}</strong><small>${x.done.length} situação(ões) registrada(s) • ${x.occurrences} ocorrência(s)</small></div><span class="profile-status mini ${s.className}">${s.label}</span><span class="teacher-arrow">→</span></button>`}).join(''):`<div class="empty card">Nenhum professor cadastrado na escala.</div>`}</div>`;
}
function salas(){const rooms=unique(state.schedule.map(x=>x.room));return `${pageHead('Salas','Mapa operacional das salas que aparecem na escala docente.') }<div class="room-grid">${rooms.map(r=>{const count=state.schedule.filter(x=>x.room===r).length;return `<article class="room-card"><div class="room-name">${esc(r)}</div><div class="room-subject">${count} registros na base</div><span class="badge other">Bloco K • Medicina</span></article>`}).join('')}</div>`}
function rondaReportRowsForPeriod(matches){
 // O relatório usa somente aulas que ainda existem na aba Ronda. Assim, uma aula
 // removida da Ronda não reaparece no relatório por causa de uma fiscalização órfã.
 const activeRows=state.schedule.filter(matches);
 const activeIds=new Set(activeRows.map(x=>String(x.id)));
 const inspections=state.inspections.filter(i=>i.status&&activeIds.has(String(i.scheduleId||'')));
 const rows=[];
 for(const lesson of activeRows){
   const linked=inspections.filter(i=>String(i.scheduleId||'')===String(lesson.id));
   if(linked.length){
     for(const i of linked){const realParts=String(i.realTime||'').split('/');rows.push({...i,date:i.date||lesson.date,day:i.day||lesson.day,start:i.start||lesson.start,end:i.end||lesson.end,plannedTime:i.plannedTime||`${lesson.start||'—'}${lesson.end?' – '+lesson.end:''}`,scheduledTeacher:i.scheduledTeacher||lesson.scheduledTeacher,subject:i.subject||lesson.subject,period:i.period||lesson.period,plannedRoom:i.plannedRoom||lesson.room,presentRoom:i.presentRoom||i.plannedRoom||lesson.room,room:i.room||i.presentRoom||i.plannedRoom||lesson.room,checkedTime:i.checkedTime||'',realStart:i.realStart||realParts[0]||'',realEnd:i.realEnd||realParts[1]||'',reportSource:'Ronda'});}
     continue;
   }
   // Compatibilidade com aulas antigas cujo resultado foi gravado diretamente na aula.
   const checks=normalizeRoomChecks(lesson).filter(c=>c.done&&c.status&&!/^pendente$/i.test(String(c.status).trim()));
   if(checks.length){
     for(const c of checks) rows.push({...lesson,status:c.status,presentTeacher:c.presentTeacher||lesson.presentTeacher||'',plannedRoom:c.room||lesson.room,presentRoom:c.presentRoom||c.room||lesson.room,room:c.room||lesson.room,checkedTime:c.checkedTime||lesson.checkedTime||'',realStart:c.realStart||lesson.realStart||'',realEnd:c.realEnd||lesson.realEnd||'',notes:c.notes||lesson.notes||'',reportSource:'Ronda'});
   } else if(lesson.status&&!/^pendente$/i.test(String(lesson.status).trim())) {
     rows.push({...lesson,plannedRoom:lesson.room,presentRoom:lesson.presentRoom||lesson.room,reportSource:'Ronda'});
   }
 }
 return rows.sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||String(a.start||a.plannedTime||'').localeCompare(String(b.start||b.plannedTime||''))||String(a.scheduledTeacher||'').localeCompare(String(b.scheduledTeacher||''),'pt-BR'));
}
function reportRowsForMonth(month){return dedupeReportRows(rondaReportRowsForPeriod(x=>String(x.date||'').startsWith(month)));}
function dedupeReportRows(rows){const seen=new Set();return rows.filter(x=>{const norm=v=>String(v??'').replace(/\s+/g,' ').trim().toLocaleLowerCase('pt-BR');const key=[x.scheduleId||'',x.date||'',x.start||x.plannedTime||'',x.end||'',x.plannedRoom||x.room||'',x.presentRoom||'',x.status||'',x.scheduledTeacher||x.assignedName||'',x.presentTeacher||'',x.subject||'',x.period||'',x.checkedTime||'',x.realStart||'',x.realEnd||'',x.notes||''].map(norm).join('|');if(seen.has(key))return false;seen.add(key);return true;});}
function reportRowsForDay(day){return dedupeReportRows(rondaReportRowsForPeriod(x=>String(x.date||'')===String(day)));}
function relatorios(){
 const day=$('#dailyReportDate')?.value||state.date; const daily=reportRowsForDay(day);
 const reportable=daily.filter(x=>x.status&&!/^pendente$/i.test(String(x.status).trim()));
 const month=$('#reportMonth')?.value||state.date.slice(0,7); const occurrences=reportRowsForMonth(month);
 const teachers=unique(occurrences.filter(x=>!['Professor não identificado','Sala vazia'].includes(x.status)).map(x=>x.scheduledTeacher||x.presentTeacher).filter(Boolean));
 const counts=occurrences.reduce((m,x)=>{m[x.status]=(m[x.status]||0)+1;return m},{});
 const statuses=reportable.reduce((m,x)=>{const status=String(x.status).trim();m[status]=(m[status]||0)+1;return m},{});
 const total=daily.length, checked=reportable.length, reportTotal=reportable.length;
 const late=reportable.filter(x=>/atras/i.test(x.status||'')||(/presente/i.test(x.status||'')&&x.realStart&&x.start&&timeToMinutes(x.realStart)>timeToMinutes(x.start))).length;
 const search=esc(state.dailySearch||''); const filter=state.dailyFilter||'all'; const q=(state.dailySearch||'').toLocaleLowerCase('pt-BR');
 const filtered=reportable.filter(x=>{const hay=[x.scheduledTeacher,x.presentTeacher,x.room,x.presentRoom,x.subject,x.period,x.status,x.notes].join(' ').toLocaleLowerCase('pt-BR');return (!q||hay.includes(q))&&(filter==='all'||(filter==='late'?/atras/i.test(x.status||'')||(/presente/i.test(x.status||'')&&x.realStart&&x.start&&timeToMinutes(x.realStart)>timeToMinutes(x.start)):filter.startsWith('status:')?String(x.status||'')===filter.slice(7):String(x.status||'').toLowerCase().includes(filter)));});
 const palette=['#315f91','#25a56a','#e5a000','#d64545','#8b5cf6','#64748b']; let offset=0; const slices=Object.entries(statuses).map(([name,n],i)=>{const start=offset;offset+=reportTotal?n/reportTotal*100:0;return {name,n,start,end:offset,color:palette[i%palette.length]}});
 const pie=slices.length?`<div class="daily-pie" style="background:conic-gradient(${slices.map(s=>`${s.color} ${s.start}% ${s.end}%`).join(',')})"><div class="daily-pie-hole"><strong>${total}</strong><span>registros</span></div></div><div class="daily-legend">${slices.map(s=>`<div><i style="background:${s.color}"></i><span>${esc(s.name)}</span><strong>${s.n}</strong></div>`).join('')}</div>`:'<div class="empty">Sem dados para montar o gráfico.</div>';
 return `${pageHead('Relatórios','Acompanhe o dia em poucos segundos e consulte ocorrências por professor, situação ou sala.',`<button class="btn primary" id="generateDailyPdf">Relatório diário / PDF</button><button class="btn ghost" id="exportCsv">Exportar CSV mensal</button>`)}
 <section class="card panel daily-report-panel"><div class="daily-report-head"><div><span class="eyebrow">RELATÓRIO OPERACIONAL</span><h2>Resumo diário</h2><p class="muted">Visão consolidada das aulas que estão na Ronda e das fiscalizações registradas.</p></div><label class="daily-date-label">Data do relatório<input class="control" type="date" id="dailyReportDate" value="${esc(day)}"></label></div>
 <div class="daily-kpis"><div class="daily-kpi"><span>Aulas na Ronda</span><strong>${state.schedule.filter(x=>String(x.date||'')===day).length}</strong><small>programadas para o dia</small></div><div class="daily-kpi success"><span>Presenças registradas</span><strong>${daily.filter(x=>/presente/i.test(x.status||'')&&!/não identificado/i.test(x.status||'')).length}</strong><small>professores identificados como presentes</small></div><div class="daily-kpi"><span>Registros fiscalizados</span><strong>${checked}</strong><small>com situação registrada</small></div><div class="daily-kpi attention"><span>Atrasos identificados</span><strong>${late}</strong><small>conforme situação/horário</small></div><div class="daily-kpi"><span>Outras ocorrências</span><strong>${daily.filter(x=>x.status&&!/presente/i.test(x.status)).length}</strong><small>ausências, substituições e demais situações</small></div></div>
 <div class="daily-insights-grid"><div class="daily-chart-card"><div class="panel-head"><h3>Situações do dia</h3><span class="muted">${fmtDate(day)}</span></div><div class="daily-chart-content">${pie}</div></div><div class="daily-note-card"><h3>Leitura rápida</h3><p>${total?`Foram encontrados <strong>${total}</strong> registros para a data. <strong>${checked}</strong> já possuem situação preenchida${late?`, com <strong>${late}</strong> possível(is) atraso(s) para revisar`:'; nenhum atraso foi identificado pelos dados disponíveis'}.`:'Não há aulas ou fiscalizações registradas para esta data.'}</p><div class="daily-progress"><div><span>Registros com situação</span><strong>${checked}</strong></div><div class="daily-progress-track"><i style="width:${total?checked/total*100:0}%"></i></div></div><button class="btn ghost small" id="showDailyLate">Ver somente atrasos</button></div></div>
 <div class="daily-status-overview"><div class="panel-head"><div><h3>Todas as situações</h3><p class="muted">Distribuição atualizada conforme os registros do dia são preenchidos.</p></div><span class="daily-result-count">${Object.keys(statuses).length} categoria(s)</span></div><div class="daily-status-grid">${Object.entries(statuses).sort((a,b)=>{if(a[0]==='Presente')return -1;if(b[0]==='Presente')return 1;return b[1]-a[1]||a[0].localeCompare(b[0],'pt-BR')}).map(([name,n],i)=>`<button class="daily-status-chip" data-status-chip="${esc(name)}" title="Filtrar por ${esc(name)}"><span class="daily-status-dot" style="background:${palette[i%palette.length]}"></span><span>${esc(name)}</span><strong>${n}</strong></button>`).join('')||'<div class="empty">As situações aparecerão aqui conforme forem registradas.</div>'}</div></div></section>
 <section class="card panel daily-search-panel"><div class="panel-head"><div><h2>Pesquisar registros do dia</h2><p class="muted">Busque pelo nome do professor, sala, disciplina ou observação.</p></div><span class="daily-result-count">${filtered.length} resultado(s)</span></div><div class="daily-search-controls"><input class="control" id="dailyTeacherSearch" value="${search}" placeholder="Ex.: nome do professor, sala 507…"><select class="control" id="dailyStatusFilter"><option value="all" ${filter==='all'?'selected':''}>Todas as situações</option><option value="late" ${filter==='late'?'selected':''}>Atrasos</option><option value="substit" ${filter==='substit'?'selected':''}>Substituições</option><option value="ausente" ${filter==='ausente'?'selected':''}>Ausências</option><option value="just" ${filter==='just'?'selected':''}>Justificadas</option>${filter.startsWith('status:')?`<option value="${esc(filter)}" selected>${esc(filter.slice(7))}</option>`:''}</select><button class="btn ghost" id="clearDailySearch">Limpar</button></div>
 ${filtered.length?`<div class="table-wrap"><table class="daily-table"><thead><tr><th>Horário</th><th>Professor escalado</th><th>Professor presente</th><th>Sala</th><th>Situação</th><th>Observação</th></tr></thead><tbody>${filtered.slice(0,150).map(x=>`<tr><td><strong>${esc(x.start||x.plannedTime||'—')}</strong>${x.realStart?`<small class="cell-sub">Real: ${esc(x.realStart)}${x.realEnd?' – '+esc(x.realEnd):''}</small>`:''}</td><td>${esc(x.scheduledTeacher||x.assignedName||'—')}</td><td>${esc(x.presentTeacher||'—')}</td><td>${esc(x.presentRoom||x.plannedRoom||x.room||'—')}</td><td>${badge(x.status)}</td><td>${esc(x.notes||'—')}</td></tr>`).join('')}</tbody></table>${filtered.length>150?`<p class="muted">Exibindo 150 de ${filtered.length} resultados. Refine a busca para localizar um registro.</p>`:''}</div>`:'<div class="empty">Nenhum registro corresponde aos filtros. Tente outra busca ou selecione outra situação.</div>'}</section>
 <details class="monthly-report-details" open><summary>Relatório mensal completo <span class="muted">${fmtMonth(month)}</span></summary><div class="report-layout"><section class="card panel"><div class="panel-head"><h2>Resumo do mês</h2></div><div class="monthly-report-tools"><input class="control" type="month" id="reportMonth" value="${month}"><button class="btn primary" id="generatePdf">Gerar PDF mensal</button></div><div class="kpi"><span>Total de fiscalizações registradas</span><strong>${occurrences.length}</strong></div><div class="kpi"><span>Professores identificados fiscalizados</span><strong>${teachers.length}</strong></div><div class="kpi"><span>Professor não identificado</span><strong>${counts['Professor não identificado']||0}</strong></div><div class="kpi"><span>Sala vazia</span><strong>${counts['Sala vazia']||0}</strong></div>${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([n,v])=>`<div class="kpi"><span>${esc(n)}</span><strong>${v}</strong></div>`).join('')||'<div class="empty">Nenhuma fiscalização com situação registrada no período selecionado.</div>'}</section><section class="card panel"><div class="panel-head"><h2>Prévia dos registros</h2><span class="muted">${fmtMonth(month)}</span></div>${occurrences.length?`<div class="monthly-record-cards">${occurrences.map((x,i)=>`<article class="monthly-record-card"><div class="monthly-record-card-head"><div><span class="record-index">REGISTRO ${String(i+1).padStart(2,'0')}</span><h3>${esc(x.subject||'Disciplina não informada')}</h3><p>${fmtDate(x.date)}${x.day?' · '+esc(x.day):''} · ${esc(x.period||'Período não informado')}</p></div><div class="record-status">${badge(x.status||'Sem situação')}</div></div><div class="monthly-record-fields"><div><span>Horário da aula</span><strong>${esc(x.start&&x.end?x.start+'–'+x.end:(x.plannedTime||'—'))}</strong>${x.realStart||x.realEnd?`<small>Real: ${esc(x.realStart||'—')}${x.realEnd?'–'+esc(x.realEnd):''}</small>`:''}</div><div><span>Horário fiscal</span><strong>${esc(x.checkedTime||'Não informado')}</strong></div><div><span>Professor escalado</span><strong>${esc(x.scheduledTeacher||x.assignedName||'—')}</strong></div><div><span>Professor presente</span><strong>${esc(x.presentTeacher||'—')}</strong></div><div><span>Sala prevista</span><strong>${esc(x.plannedRoom||x.room||'—')}</strong></div><div><span>Sala fiscalizada</span><strong>${esc(x.presentRoom||x.room||x.plannedRoom||'—')}</strong></div></div><div class="monthly-record-notes"><span>Observações</span><p>${esc(x.notes||'Nenhuma observação registrada.')}</p></div></article>`).join('')}</div>`:'<div class="empty">Nenhuma fiscalização com situação registrada no período.</div>'}</section></div></details>`;
}

function config(){return `${pageHead('Configurações','Preferências, segurança dos dados e atualização do aplicativo.') }<div class="dashboard-grid"><section class="card panel"><div class="panel-head"><h2>Identificação</h2></div><label class="muted">Responsável<input class="control" style="width:100%;margin-top:6px" id="cfgResponsible" value="${esc(state.settings.responsible||APP_META.responsible)}"></label><br><button class="btn primary" id="saveConfig">Salvar alterações</button></section><section class="card panel"><div class="panel-head"><h2>Dados</h2></div><p class="muted">O aplicativo usa IndexedDB no navegador para manter os registros neste dispositivo.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" id="backupBtn">Fazer backup</button><label class="btn ghost">Restaurar backup<input type="file" id="restoreFile" accept="application/json" hidden></label></div></section><section class="card panel"><div class="panel-head"><h2>Backup na nuvem — Supabase</h2></div><p class="muted">Os registros continuam neste dispositivo até você entrar e sincronizar. A sincronização envia os dados locais e baixa somente registros ausentes; não apaga registros na nuvem.</p><div id="cloudStatus" class="muted" style="margin:8px 0">Verificando sessão...</div><div id="cloudLoginFields"><label class="muted">E-mail do Supabase<input class="control" style="width:100%;margin-top:6px" type="email" id="cloudEmail" autocomplete="username" placeholder="seu e-mail"></label><br><label class="muted">Senha<input class="control" style="width:100%;margin-top:6px" type="password" id="cloudPassword" autocomplete="current-password" placeholder="Senha do usuário Supabase"></label><br><button class="btn primary" id="cloudLogin">Entrar no Supabase</button></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn primary" id="cloudSync">Sincronizar agora</button><button class="btn ghost" id="cloudLogout">Sair da conta</button></div><small class="muted">Importante: mantenha backups locais. Se houver conflito na mesma chave, a cópia local prevalece nesta versão.</small></section><section class="card panel"><div class="panel-head"><h2>Atualizações</h2><span id="updateStatus" class="muted">Versão atual: V6.17.0</span></div><p class="muted">Verifique se existe uma nova versão publicada e atualize sem apagar seus registros locais.</p><button class="btn primary" id="checkUpdate">Verificar atualização</button></section></section></div>`}

