async function checkForUpdate(){try{if(!('serviceWorker' in navigator)){toast('Atualização automática não está disponível neste navegador.','error');return;}const reg=await navigator.serviceWorker.getRegistration();if(!reg){toast('Service Worker ainda não está ativo. Reabra o aplicativo e tente novamente.','error');return;}toast('Verificando atualização...');await reg.update();await new Promise(r=>setTimeout(r,500));if(reg.waiting){reg.waiting.postMessage({type:'SKIP_WAITING'});toast('Atualização encontrada. Recarregando...');setTimeout(()=>location.reload(),900);return;}toast('Você já está usando a versão mais recente.')}catch(err){console.error(err);toast('Não foi possível verificar a atualização.','error')}}
function exportCSV(){const month=$('#reportMonth')?.value||state.date.slice(0,7);const rows=reportRowsForMonth(month);const head='data;dia;horario_aula;horario_fiscal;horario_real_inicio;horario_real_fim;periodo;sala_prevista;sala_fiscalizada;professor_escalado;professor_presente;disciplina;situacao;observacoes';const body=rows.map(x=>[x.date,x.day||(x.date?new Date(x.date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long'}):''),x.start&&x.end?x.start+' - '+x.end:(x.plannedTime||''),x.checkedTime,x.realStart,x.realEnd,x.period,x.plannedRoom||x.room,x.presentRoom||x.room||x.plannedRoom,x.scheduledTeacher||x.assignedName,x.presentTeacher,x.subject,x.status,x.notes].map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n');download(`relatorio-${month}.csv`,'\ufeff'+head+'\n'+body,'text/csv;charset=utf-8')}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+(type==='error'?'error':'');el.textContent=msg;$('#toastHost').appendChild(el);setTimeout(()=>el.remove(),3200)}

async function updateCloudStatus(){const el=$('#cloudStatus');const fields=$('#cloudLoginFields');if(!el)return;const info=cloud.sessionInfo();if(info){el.textContent=`Conectado como ${info.email}. Dados locais permanecem disponíveis.`;if(fields)fields.style.display='none';}else{el.textContent='Não conectado. Entre com o usuário criado em Supabase → Authentication → Users.';if(fields)fields.style.display='block';}}
async function cloudLogin(){const email=$('#cloudEmail')?.value.trim(),password=$('#cloudPassword')?.value;if(!email||!password){toast('Informe e-mail e senha do usuário Supabase.','error');return;}const btn=$('#cloudLogin');if(btn)btn.disabled=true;try{await cloud.signIn(email,password);if($('#cloudPassword'))$('#cloudPassword').value='';await updateCloudStatus();toast('Login realizado. Agora você pode sincronizar.');}catch(err){console.error(err);toast(`Falha no login: ${err.message}`,'error');}finally{if(btn)btn.disabled=false;}}
async function cloudSyncNow(){const btn=$('#cloudSync');if(btn)btn.disabled=true;try{toast('Sincronizando registros com a nuvem...');const result=await cloud.syncDatabase(db);await reload();render();toast(`Sincronização concluída: ${result.uploaded} enviados e ${result.downloaded} recuperados.`);await updateCloudStatus();}catch(err){console.error(err);toast(`Sincronização não concluída: ${err.message}`,'error');}finally{if(btn)btn.disabled=false;}}
async function cloudLogout(){await cloud.signOut();await updateCloudStatus();toast('Sessão do Supabase encerrada neste dispositivo.');}
